 [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr OpenProcess(uint access,bool inherit,int pid);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool CloseHandle(IntPtr h);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool ReadProcessMemory(IntPtr h,IntPtr a,byte[] b,IntPtr size,out IntPtr n);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool WriteProcessMemory(IntPtr h,IntPtr a,byte[] b,IntPtr size,out IntPtr n);
 [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr VirtualAllocEx(IntPtr h,IntPtr a,IntPtr size,uint type,uint protection);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool VirtualFreeEx(IntPtr h,IntPtr a,IntPtr size,uint type);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool VirtualProtectEx(IntPtr h,IntPtr a,IntPtr size,uint protection,out uint old);
 [DllImport("kernel32.dll",SetLastError=true)] static extern bool FlushInstructionCache(IntPtr h,IntPtr a,IntPtr size);
 static void Check(bool ok,string message){if(!ok)throw new InvalidOperationException(message+" (Win32 "+Marshal.GetLastWin32Error()+")");}
 static byte[] Read(IntPtr h,long a,int size){byte[] b=new byte[size];IntPtr n;Check(ReadProcessMemory(h,new IntPtr(a),b,new IntPtr(size),out n)&&n.ToInt64()==size,"Read memory");return b;}
 static void Write(IntPtr h,long a,byte[] b){IntPtr n;Check(WriteProcessMemory(h,new IntPtr(a),b,new IntPtr(b.Length),out n)&&n.ToInt64()==b.Length,"Write memory");}
 static bool Equal(byte[] a,byte[] b){if(a.Length!=b.Length)return false;for(int i=0;i<a.Length;i++)if(a[i]!=b[i])return false;return true;}
 static string Sha(string path){using(var s=SHA256.Create())using(var f=File.OpenRead(path))return BitConverter.ToString(s.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 static byte[] Redirect(long entry,long cave,int size){byte[] b=new byte[size];for(int i=0;i<size;i++)b[i]=0x90;b[0]=0xe9;Buffer.BlockCopy(BitConverter.GetBytes(checked((int)(cave-entry-5))),0,b,1,4);return b;}
 static void ProtectedWrite(IntPtr h,long entry,byte[] value,ref uint originalProtection){uint old;Check(VirtualProtectEx(h,new IntPtr(entry),new IntPtr(value.Length),RWX,out old),"Protect redirect");if(originalProtection==0)originalProtection=old;try{Write(h,entry,value);Check(FlushInstructionCache(h,new IntPtr(entry),new IntPtr(value.Length)),"Flush redirect");Check(Equal(Read(h,entry,value.Length),value),"Verify redirect");}finally{uint ignored;Check(VirtualProtectEx(h,new IntPtr(entry),new IntPtr(value.Length),originalProtection,out ignored),"Restore redirect protection");}}
 static IntPtr Allocate(IntPtr h,long image){for(long d=0x20000000;d<=0x60000000;d+=0x10000){var a=VirtualAllocEx(h,new IntPtr(image+d),new IntPtr(0x9000),0x3000,RW);if(a!=IntPtr.Zero)return a;}return IntPtr.Zero;}
 static Process Supported(int pid){var p=Process.GetProcessById(pid);if(!String.Equals(p.ProcessName,"Zoe2Mars",StringComparison.OrdinalIgnoreCase)||Sha(p.MainModule.FileName)!=ExpectedExe)throw new Exception("Unsupported game process/executable");return p;}
 static void Attach(int pid){
  var process=Supported(pid);long image=process.MainModule.BaseAddress.ToInt64();IntPtr h=OpenProcess(0x438,false,pid);Check(h!=IntPtr.Zero,"Open game process");
  IntPtr allocation=IntPtr.Zero;bool committed=false,uncertain=false;var attempted=new List<Hook>();
  try{
   foreach(var hook in Hooks)if(!Equal(Read(h,image+hook.Entry-ImageBase,hook.Stolen.Length),hook.Stolen))throw new Exception("Native Aumaan bytes differ or a conflicting helper is active at "+hook.Entry.ToString("x"));
   allocation=Allocate(h,image);Check(allocation!=IntPtr.Zero,"Allocate Aumaan code/configuration");long cave=allocation.ToInt64();byte[] code=BuildCave(image,cave),config=Config(image);
   Write(h,cave,code);Write(h,cave+0x8000,config);Check(Equal(Read(h,cave,code.Length),code)&&Equal(Read(h,cave+0x8000,config.Length),config),"Verify Aumaan payload");
   uint old;Check(VirtualProtectEx(h,allocation,new IntPtr(0x8000),RX,out old),"Protect Aumaan code");Check(FlushInstructionCache(h,allocation,new IntPtr(code.Length)),"Flush Aumaan code");
   foreach(var hook in Hooks){attempted.Add(hook);ProtectedWrite(h,image+hook.Entry-ImageBase,Redirect(image+hook.Entry-ImageBase,cave+hook.Cave,hook.Stolen.Length),ref hook.Protection);}
   committed=true;Console.WriteLine("Aumaan shuffled-arena healing animation and combat distance guard active. Disk executable unchanged.");
  }catch(Exception failure){
   for(int i=attempted.Count-1;i>=0;i--){var hook=attempted[i];try{ProtectedWrite(h,image+hook.Entry-ImageBase,hook.Stolen,ref hook.Protection);}catch{uncertain=true;}}
   if(uncertain)throw new Exception("Aumaan attachment failed and rollback could not be verified. Close the game. "+failure.Message);
   throw;
  }finally{if(allocation!=IntPtr.Zero&&!committed&&!uncertain)VirtualFreeEx(h,allocation,IntPtr.Zero,0x8000);CloseHandle(h);}
 }
 static void Capture(int pid,string output){
  var process=Supported(pid);long image=process.MainModule.BaseAddress.ToInt64();
  IntPtr h=OpenProcess(0x410,false,pid);Check(h!=IntPtr.Zero,"Open read-only Aumaan status");
  try {
   long entry=image+Hooks[0].Entry-ImageBase;
   byte[] redirect=Read(h,entry,5);
   if(redirect[0]!=0xe9)throw new Exception("Aumaan combat helper is not attached");
   long cave=entry+5+BitConverter.ToInt32(redirect,1);byte[] code=BuildCave(image,cave);
   if(!Equal(Read(h,cave,code.Length),code))throw new Exception("A different helper occupies the Aumaan update entry");
   byte[] c=Read(h,cave+0x8000,Config(image).Length);
   string stage=System.Text.Encoding.ASCII.GetString(Read(h,image+0x1535830,8)).Split((char)0)[0];
   string seed="unknown";string manifest=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","manifest.json");
   if(File.Exists(manifest)){
    var data=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadAllText(manifest));
    if(data.ContainsKey("seed"))seed=Convert.ToString(data["seed"]);
   }
   var report=new {format=1,seed=seed,arena=stage,variant="Aumaan Anubis",
    last_arena=System.Text.Encoding.ASCII.GetString(c,64,8).Split((char)0)[0],
    spawns=BitConverter.ToUInt32(c,48),heal_entries_blocked=BitConverter.ToUInt32(c,52),
    shared_motion_entries_blocked=BitConverter.ToUInt32(c,88),last_blocked_state=BitConverter.ToUInt32(c,92),
    returns_to_player=BitConverter.ToUInt32(c,56),blocked_return_destinations=BitConverter.ToUInt32(c,60),
    actor=BitConverter.ToUInt32(c,72).ToString("x8"),state=BitConverter.ToUInt32(c,76),
    pending_state=BitConverter.ToUInt32(c,80),motion=BitConverter.ToUInt32(c,84)};
   File.WriteAllText(output,new JavaScriptSerializer().Serialize(report));
   Console.WriteLine("Read-only Aumaan status captured: "+output);
  } finally {CloseHandle(h);}
 }
 static void SelfTest(string folder){Directory.CreateDirectory(folder);foreach(long image in new long[]{ImageBase,0x180000000,0x7ff600000000})foreach(long offset in new long[]{0x20000000,0x20010000,0x60000000}){long cave=image+offset;byte[] b=BuildCave(image,cave),c=Config(image);if(c.Length!=288||b.Length>=0x8000)throw new Exception("Aumaan payload bounds");File.WriteAllBytes(Path.Combine(folder,"aumaan-"+image.ToString("x")+"-"+offset.ToString("x")+".bin"),b);File.WriteAllBytes(Path.Combine(folder,"config-"+image.ToString("x")+".bin"),c);}Console.WriteLine("Aumaan payload fixtures at three bases and three cave offsets; no game opened.");}
 public static int Main(string[] args){try{if(args.Length==2&&args[0]=="--self-test"){SelfTest(args[1]);return 0;}if(args.Length==2&&args[0]=="--attach-menu"){Attach(Int32.Parse(args[1]));return 0;}if(args.Length==3&&args[0]=="--capture-status"){Capture(Int32.Parse(args[1]),args[2]);return 0;}Console.WriteLine("--self-test folder; --attach-menu PID; --capture-status PID output.json");return 0;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}}
}
